package solution

import (
	"errors"
	"sort"
)

type Component struct {
	Name    string
	Scope   string
	Release string
	Quota   int
}

type Registry struct {
	items map[string]Component
}

func NewRegistry() *Registry {
	return &Registry{items: make(map[string]Component)}
}

func componentKey(name, scope string) string { return scope + "\x00" + name }

func (r *Registry) Create(name, scope, release string) (Component, error) {
	if name == "" || scope == "" || release == "" {
		return Component{}, errors.New("all fields are required")
	}
	k := componentKey(name, scope)
	if _, ok := r.items[k]; ok {
		return Component{}, errors.New("component already exists")
	}
	c := Component{Name: name, Scope: scope, Release: release, Quota: 64}
	r.items[k] = c
	return c, nil
}

func (r *Registry) List(scope string) []Component {
	out := make([]Component, 0)
	if scope == "" {
		return out
	}
	for _, c := range r.items {
		if c.Scope == scope {
			out = append(out, c)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func (r *Registry) Get(name, scope string) (Component, error) {
	if name == "" || scope == "" {
		return Component{}, errors.New("name and scope are required")
	}
	c, ok := r.items[componentKey(name, scope)]
	if !ok {
		return Component{}, errors.New("component not found")
	}
	return c, nil
}

func (r *Registry) Delete(name, scope string) error {
	if name == "" || scope == "" {
		return errors.New("name and scope are required")
	}
	k := componentKey(name, scope)
	if _, ok := r.items[k]; !ok {
		return errors.New("component not found")
	}
	delete(r.items, k)
	return nil
}
